question.answer:
def transition(n, edges):
    A = [[0.0] * n for _ in range(n)]
    for u, v in edges:
        A[u][v] = 1.0
        A[v][u] = 1.0
    P = []
    for u in range(n):
        d = sum(A[u])
        if d == 0:
            P.append([0.0] * n)
        else:
            P.append([a / d for a in A[u]])
    return P


def stationary(n, edges):
    d = [0] * n
    for u, v in edges:
        d[u] += 1
        d[v] += 1
    total = sum(d)
    if total == 0:
        return [0.0] * n
    return [x / total for x in d]

