question.answer:
def pagerank(n, out_links, alpha, n_iter):
    r = [1.0 / n] * n
    for _ in range(n_iter):
        new = [0.0] * n
        dangling = 0.0
        for u in range(n):
            succ = out_links[u]
            if not succ:
                dangling += r[u]
                continue
            share = r[u] / len(succ)
            for v in succ:
                new[v] += share
        base = (1.0 - alpha) / n + alpha * dangling / n
        r = [base + alpha * x for x in new]
    return r

