question.answer:
def node2vec_probs(adj, t, v, p, q):
    tset = set(adj[t])
    weights = {}
    for x in adj[v]:
        if x == t:
            w = 1.0 / p
        elif x in tset:
            w = 1.0
        else:
            w = 1.0 / q
        weights[x] = w
    total = sum(weights.values())
    if total == 0:
        return {x: 0.0 for x in weights}
    return {x: w / total for x, w in weights.items()}

