question.answer:
import math


def common_neighbors(adj, u, v):
    return len(set(adj[u]) & set(adj[v]))


def jaccard(adj, u, v):
    a, b = set(adj[u]), set(adj[v])
    union = a | b
    if not union:
        return 0.0
    return len(a & b) / len(union)


def adamic_adar(adj, u, v):
    total = 0.0
    for z in set(adj[u]) & set(adj[v]):
        d = len(adj[z])
        if d > 1:
            total += 1.0 / math.log(d)
    return total

testcode.text:
# a shared hub is worth less than a shared rare node
adj = {0: {9}, 1: {9}, 9: set(range(2, 200)) | {0, 1}}
hub = adamic_adar(adj, 0, 1)
adj2 = {0: {9}, 1: {9}, 9: {0, 1}}
rare = adamic_adar(adj2, 0, 1)
print(hub < rare)
